UPDATE companies SET description='Vital Farms operates Egg Central Station, its egg washing, packing, and shipping facility, in Springfield, Missouri. The company was founded in 2007 with a mission to put animal welfare first, scale family farms, and raise food quality simultaneously — a model the industry initially deemed impossible. The business began as a pasture-raised egg brand built on a network of family farms across the Pasture Belt.

The facility processes several product lines including pasture-raised eggs, organic pasture-raised eggs, restorative eggs, True Blues eggs, hard-boiled eggs, and liquid whole eggs. The company rotates more than 39,000 acres of pasture annually and reports that 59% of its farmer partners use regenerative agriculture practices.

Vital Farms sells primarily to grocery retailers across the United States, distributing its branded egg products through a national network.

The company is a certified B Corporation and operates under a stakeholder model rooted in Conscious Capitalism, legally requiring consideration of farmers, hens, crew members, stockholders, the environment, community, vendors, and consumers. Vital Farms also holds Certified Humane certification for its animal welfare standards. Its stated purpose is to improve the lives of people, animals, and the planet through food.', certifications=ARRAY['B Corp','Certified Humane']::text[], profile='{"capabilities": ["Egg washing", "Egg grading", "Egg packing", "Egg shipping", "Pasture-raised egg processing", "Organic egg processing", "Hard-boiled egg production", "Liquid whole egg processing", "Regenerative agriculture coordination"], "industries": ["Food processing", "Egg production", "Agriculture", "Retail", "Consumer packaged goods"], "materials": ["Eggs", "Egg packaging materials"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["B Corp certified", "Certified Humane", "39,000+ acres of rotated pasture annually", "#1 U.S. pasture-raised egg brand"], "facts_used": ["Founded in 2007 -> /", "Headquartered in Springfield, Missouri -> db", "Operates Egg Central Station for egg washing, packing, shipping -> /", "600+ family farm partners -> /", "39,000+ acres of pasture rotated annually -> /about", "24,000+ retailers nationwide -> /about", "B Corp certified -> /about", "Certified Humane -> /", "59% of farmers use regenerative agriculture practices -> /about", "#1 pasture-raised egg brand in U.S. -> /about", "Produces pasture-raised, organic, hard-boiled, liquid whole eggs -> /", "Stakeholder model / Conscious Capitalism -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Egg Central Station - Where our eggs are washed, packed, and shipped!", "founded_year": "2007", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, up